<?php
namespace SenderSuite;

final class ValidationFailure extends \RuntimeException {public $field;public function __construct($message,$field=null){$this->field=$field;parent::__construct($message);}}
class AuthFailure extends \RuntimeException {public $status;public function __construct($status,$message){$this->status=$status;parent::__construct($message);}}
final class DetailedFailure extends AuthFailure {public $detail;public function __construct($status,array $detail){$this->detail=$detail;parent::__construct($status,$detail['message']??'Request rejected.');}}
final class AuthRoutes {
    private static $context;
    public static function context(){if(self::$context===null){$wpdb=$GLOBALS['wpdb'];$db=new Database($wpdb,new Schema($wpdb->prefix));$vault=new Vault(wp_salt('auth').wp_salt('secure_auth'));$config=Config::database($db,$wpdb->prefix,$vault);self::$context=array('db'=>$db,'config'=>$config,'auth'=>new AppAuth($db,$config),'prefix'=>$wpdb->prefix);}return self::$context;}
    public static function definitions(){return array('/auth/access'=>'GET','/auth/admin'=>'POST','/auth/login'=>'POST','/auth/logout'=>'POST','/auth/me'=>'GET');}
    public static function register(){foreach(self::definitions() as $path=>$method){register_rest_route('sender-suite/v1',$path,array('methods'=>$method,'permission_callback'=>'__return_true','callback'=>array(self::class,'dispatch')));}}
    public static function error($status,$message,$id,$field=null,$validation=false){$codes=array(400=>'BAD_REQUEST',401=>'UNAUTHORIZED',403=>'FORBIDDEN',404=>'NOT_FOUND',409=>'CONFLICT',422=>'VALIDATION_ERROR',429=>'RATE_LIMITED',503=>'SERVICE_UNAVAILABLE');return array('code'=>$codes[$status]??'HTTP_ERROR','message'=>$message,'detail'=>$validation&&$field!==null?$field.': '.$message:$message,'field'=>$field,'hint'=>$validation?'Check the request fields and try again.':null,'request_id'=>$id);}
    public static function loginBody($body,$optional=false){if($body===null){if($optional){return new \stdClass();}throw new ValidationFailure('Field required');}if(!is_object($body)){throw new ValidationFailure('Input should be a valid dictionary or object to extract fields from');}$out=new \stdClass();foreach(array('username','password') as $field){$value=$body->$field??null;if($value!==null&&!is_string($value)){throw new ValidationFailure('Input should be a valid string',$field);}$out->$field=$value;}return $out;}
    public static function response($data,$status,$id){$r=new \WP_REST_Response($data,$status);$r->header('Cache-Control','no-store');$r->header('X-Request-ID',$id);return $r;}
    public static function origin($request){$origin=$request->get_header('origin');if(!$origin){return strtolower($request->get_header('sec-fetch-site'))!=='cross-site';}$site=wp_parse_url(home_url('/'));$p=wp_parse_url($origin);if(!$p||isset($p['user'])||isset($p['pass'])||isset($p['query'])||isset($p['fragment'])||!in_array($p['path']??'',array('','/'),true)){return false;}foreach(array('scheme','host') as $key){if(strtolower($p[$key]??'')!==strtolower($site[$key]??'')){return false;}}return ($p['port']??($p['scheme']==='https'?443:80))===($site['port']??($site['scheme']==='https'?443:80));}
    private static function limited(array $c,$request){$spec=$c['config']->get('RATE_LIMIT_LOGIN');preg_match('/^([1-9][0-9]*)\/(second|minute|hour|day)s?$/D',$spec,$m);$period=array('second'=>1,'minute'=>60,'hour'=>3600,'day'=>86400)[$m[2]];$ip=$_SERVER['REMOTE_ADDR']??'127.0.0.1';$key=hash('sha256',$request->get_route().':'.$ip.':'.$spec);$table=Schema::identifier($c['prefix'].'sender_suite_rate_limits');return $c['db']->transaction(function($db)use($table,$key,$period,$m){$db->execute('INSERT INTO '.$table.' (name,hits,expires_at) VALUES (%s,1,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL %d SECOND)) ON DUPLICATE KEY UPDATE hits=IF(expires_at<=UTC_TIMESTAMP(6),1,LEAST(hits+1,2147483647)),expires_at=IF(expires_at<=UTC_TIMESTAMP(6),DATE_ADD(UTC_TIMESTAMP(6),INTERVAL %d SECOND),expires_at)',array($key,$period,$period));$rows=$db->rows('SELECT hits,GREATEST(1,CEIL(TIMESTAMPDIFF(MICROSECOND,UTC_TIMESTAMP(6),expires_at)/1000000)) AS retry_after FROM '.$table.' WHERE name=%s FOR UPDATE',array($key));if(!$rows){throw new \RuntimeException('Rate-limit state missing');}return (int)$rows[0]['hits']>(int)$m[1]?max(1,(int)$rows[0]['retry_after']):0;});}
    public static function dispatch($request){$id=bin2hex(random_bytes(16));$path=substr($request->get_route(),strlen('/sender-suite/v1/'));try{if(!self::origin($request)){return self::response(self::error(403,'Cross-origin request rejected',$id),403,$id);}$c=self::context();if(!$c['config']->ready()){return self::response(self::error(503,'Application credentials are not configured. Open WordPress Settings > Sender Suite.',$id),503,$id);}$auth=$c['auth'];if($path==='auth/access'){return self::response($auth->access(),200,$id);}if($path==='auth/admin'||$path==='auth/login'){if(($retry=self::limited($c,$request))>0){$r=self::response(self::error(429,'Too many requests. Please slow down and try again shortly.',$id),429,$id);$r->header('Retry-After',(string)$retry);return $r;}$raw=$request->get_body();try{$body=$raw===''?null:json_decode($raw,false,512,JSON_THROW_ON_ERROR);}catch(\Throwable $e){throw new ValidationFailure('JSON decode error');}$body=self::loginBody($body,$path==='auth/admin');$signed=$c['db']->transaction(function()use($auth,$path,$c,$body){$user=$auth->authenticate($path==='auth/admin'?$c['config']->get('ADMIN_USERNAME'):($body->username??null),$body->password??null);if($user===null){throw new AuthFailure(401,$path==='auth/admin'?'Wrong password. Use the configured app password.':'Invalid username or password');}return $auth->signIn($user);});$r=self::response($signed['body'],200,$id);$cookie='sendsms_session='.$signed['token'].'; Path=/; Max-Age='.($c['config']->get('ACCESS_TOKEN_EXPIRE_MINUTES')*60).'; HttpOnly; SameSite=lax';}else{$user=$auth->current(isset($_COOKIE['sendsms_session'])?wp_unslash($_COOKIE['sendsms_session']):null);if($user===null){return self::response(self::error(401,'Not authenticated',$id),401,$id);}if($path==='auth/me'){return self::response(AppAuth::userOut($user),200,$id);}if($path!=='auth/logout'){return self::response(self::error(404,'Not Found',$id),404,$id);}$r=self::response(array('success'=>true,'message'=>'Logged out'),200,$id);$cookie='sendsms_session=; Path=/; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; HttpOnly; SameSite=lax';}if($c['config']->get('APP_ENV')==='production'){$cookie.='; Secure';}$r->header('Set-Cookie',$cookie);return $r;}catch(AuthFailure $e){return self::response(self::error($e->status,$e->getMessage(),$id),$e->status,$id);}catch(ValidationFailure $e){return self::response(self::error(422,$e->getMessage(),$id,$e->field,true),422,$id);}catch(\Throwable $e){return self::response(self::error(503,'Application service is unavailable.',$id),503,$id);}}
}
